# 每條長條的位置
# 透過較大的間距分成 1：2：2 三組
x_positions = [0, 0.9, 1.55, 2.45, 3.10]

bar_labels = [
    "Baseline",
    "XDP",
    "User",
    "XDP",
    "User"
]

colors = [
    "gray",
    "tab:blue",
    "tab:orange",
    "tab:blue",
    "tab:orange"
]

# 圖寬縮小，方便之後旁邊放其他圖
fig, ax = plt.subplots(figsize=(4.3, 5))

bars = ax.bar(
    x_positions,
    means,
    width=0.52,
    edgecolor="black",
    linewidth=1,
    color=colors
)

ax.set_xticks(x_positions)
ax.set_xticklabels(bar_labels, fontsize=10)

ax.set_ylabel("CPU (%)", fontsize=12)
# ax.set_title("Average CPU Usage", fontsize=13)

ax.grid(axis="y", linestyle="--", alpha=0.4)
ax.set_axisbelow(True)

for bar, value in zip(bars, means):
    ax.text(
        bar.get_x() + bar.get_width() / 2,
        bar.get_height(),
        f"{value:.2f}%",
        ha="center",
        va="bottom",
        fontsize=9
    )

# 三組名稱的位置
group_centers = [
    0,
    (0.9 + 1.55) / 2,
    (2.45 + 3.10) / 2
]

group_labels = ["", "50%", "75%"]

for center, label in zip(group_centers, group_labels):
    ax.text(
        center,
        -0.08,  
        label,
        ha="center",
        va="top",
        fontsize=11,
        fontweight="bold",
        transform=ax.get_xaxis_transform()
    )

# 減少左右空白
ax.set_xlim(-0.45, 3.55)

plt.subplots_adjust(bottom=0.21)
plt.tight_layout()
plt.savefig('result/limiter_bar.png', dpi=300)
plt.show()